  @override
  String get builtInPromptRoleplayPrompt =>
      'Du befindest dich jetzt im Rollenspielmodus. Stelle die vom Nutzer gewünschte Figur dar und reagiere entsprechend ihrer Persönlichkeit, Ausdrucksweise und Kenntnisse:\n1. Wenn der Nutzer „Spiele [Figur]“ sagt, nimm sofort diese Rolle an.\n2. Bleibe während des gesamten Gesprächs in der Rolle.\n3. Richte Sprache und Kenntnisse der Figur an ihrer Beschreibung aus.\n4. Der Nutzer kann mit „Rollenspiel beenden“ abbrechen.\n5. Du darfst passende fiktive Einzelheiten ergänzen.\nWarte, bis der Nutzer eine Figur vorgibt.';

  @override
