  @override
  String get batchDlgHelpBody =>
      '1. Wähle eine Voreinstellung aus oder aktiviere Regeln. Kopiere anschließend Regeln und passe bei Bedarf ihre Reihenfolge an.\n\n2. In der Vorschau siehst du die verwendeten Namen. Suche und Filter ändern nur die Anzeige. Wenn du ein Element abwählst, wird es ausgeschlossen und die Nummerierung neu berechnet. Bearbeite einzelne Namen oder stelle das Regelergebnis wieder her.\n\n3. Behebe alle Probleme vor dem Start. Automatische Suffixe lösen doppelte Namen, ohne Dateien zu überschreiben. Benenne Ordner, die Namen tauschen, in getrennten Stapeln um.\n\n4. Du kannst spätere Elemente während der Ausführung anhalten; das aktuelle Element wird zuerst abgeschlossen. Auf der Ergebnisseite siehst du die abgeschlossenen Änderungen und kannst sie rückgängig machen. Das ist nicht möglich, wenn sich die Liste seit der Ausführung geändert hat.\n\nEs werden nur Namen und Ordnerpfade geändert, nicht die Dateiinhalte oder -erweiterungen. Wenn du einen übergeordneten Ordner umbenennst, können ausgewählte Unterelemente weiterhin umbenannt werden; außerdem werden seine Unterordner mitverschoben.';

