  @override
  String get backgroundOptimizationColdStartTitle =>
      'Dienst beim App-Start wiederherstellen';

  @override
  String get backgroundOptimizationColdStartDetail =>
      'Wenn aktiviert, sucht die App bei jedem Start nach einem zuvor ausgeführten Hintergrunddienst und stellt ihn wieder her.\n\nWenn das System oder der Nutzer den App-Prozess beendet, wird der Hintergrunddienst beim nächsten Öffnen der App neu gestartet.\n\nFür alle Nutzer empfohlen.\nAuswirkung auf den Akku: keine; die App prüft den Status nur einmal beim Start.';

  @override
  String get backgroundOptimizationSaveColdStartFailed =>
      'Einstellung zur Wiederherstellung beim Start konnte nicht gespeichert werden; sie wurde nicht geändert';

  @override
  String get backgroundOptimizationBatteryReminderTitle =>
      'Erinnerung an Akkusparen';

  @override
  String get backgroundOptimizationBatteryReminderDetail =>
      'Wenn aktiviert, zeigt diese Seite den Status der Akkuoptimierung an. Wenn die App nicht auf der Ausnahmeliste steht, kannst du die Systemeinstellungen öffnen, um sie hinzuzufügen.\n\nDie Android-Akkuoptimierung (Doze) beschränkt Hintergrund-Apps. Wird diese App zur Ausnahmeliste hinzugefügt, verhindert dies, dass das System sie zum Energiesparen beendet.\n\nWenn du diese Option deaktivierst, wird nur die Erinnerungskarte ausgeblendet; die Akku-Ausnahme der App wird dadurch nicht geändert.';

  @override
  String get backgroundOptimizationStrategyIntro =>
      'Diese Strategien können unabhängig voneinander aktiviert werden. Für möglichst zuverlässige Hintergrundaktivität sind standardmäßig alle aktiviert. Wenn du eine deaktivierst, wirkt sich das nur auf diese Strategie aus, nicht auf den Hintergrunddienst selbst.';

  @override
  String get backgroundOptimizationIosNoteTitle => 'iOS-Hintergrundaufgaben';

  @override
  String get backgroundOptimizationIosSupported =>
      'Diese iOS-Version (26 oder neuer) unterstützt fortlaufende Hintergrundaufgaben. Aufgaben laufen normalerweise weiter, wenn du zu einer anderen App wechselst oder den Bildschirm sperrst. Bei knappen Ressourcen kann das System sie jedoch beenden. Den Fortschritt kannst du auf dem Sperrbildschirm sehen.';

  @override
  String get backgroundOptimizationIosUnsupported =>
      'Diese iOS-Version (älter als 26) unterstützt keine fortlaufenden Hintergrundaufgaben. Wechsle während einer laufenden Aufgabe alle paar Minuten zurück zur App (etwa alle 5–10 Minuten, abhängig von iOS), um die Hintergrundzeit zu erneuern und eine Unterbrechung zu verhindern.';

  @override
  String get backgroundOptimizationIosWarning =>
      'Unter keiner iOS-Version solltest du Stroom im App-Umschalter wegwischen. Dadurch werden alle laufenden Aufgaben sofort beendet.';

  @override
  String get backgroundOptimizationDesktopIntro =>
