      'Beim Schließen des Fensters minimieren';

  @override
  String get backgroundOptimizationCloseMinimizeDetail =>
      'Wenn aktiviert, blendet die Schaltfläche zum Schließen die App in der Systemleiste aus, anstatt sie zu beenden. Hintergrundaufgaben laufen weiter.\n\nDu kannst das Fenster über das Symbol in der Systemleiste oder den Menüpunkt „Hauptfenster anzeigen“ wiederherstellen. Zum Beenden verwendest du die Schaltfläche „App beenden“ unten.\n\nFür alle Desktopnutzer empfohlen.';

