  @override
  String asrFailureDiagnosticFormat(
    Object category,
    Object stage,
    Object chunk,
    Object message,
  ) {
    return 'ASR $category bei $stage$chunk: $message';
  }

  @override
  String asrFailureChunkPosition(Object index, Object count) {
    return ', Segment $index/$count';
  }

  @override
  String asrFailureRequestFailed(Object detail) {
    return 'Anfrage fehlgeschlagen: $detail';
  }

  @override
  String asrChunkAllFailed(Object count) {
    return 'Transkription mit Segmentierung fehlgeschlagen ($count Segmente, keines erfolgreich)';
  }

  @override
  String asrChunkIncomplete(Object succeeded, Object count) {
    return 'Transkription mit Segmentierung unvollständig ($succeeded/$count Segmente erfolgreich)';
  }

  @override
  String asrChunkSucceeded(Object detail) {
    return 'Erfolgreich: $detail';
  }

  @override
  String asrChunkFailed(Object detail) {
    return 'Fehlgeschlagen: $detail';
  }

  @override
  String asrChunkUncertain(Object detail) {
    return 'Ergebnis ungewiss: $detail';
  }

  @override
  String asrChunkDetails(
    Object index,
    Object start,
    Object end,
    Object status,
  ) {
    return 'Segment $index ($start–${end}s) $status';
  }

  @override
  String asrChunkCheckpointFailure(Object detail) {
    return 'Speichern des Segmentstatus fehlgeschlagen: $detail';
  }

  @override
  String get asrChunkUncertainGuidance =>
      'Das Ergebnis der Anfrage ist ungewiss. Der erneute Versuch wurde beendet, um doppelte Übermittlungen zu vermeiden. Wähle das Audio erneut aus, um eine neue Aufgabe zu erstellen.';

  @override
  String asrRetryAudioLost(Object audioName) {
    return 'Die ursprüngliche Audiodatei ist verloren gegangen. Wähle das Audio erneut aus, um es erneut zu versuchen: $audioName';
  }

