      'Stroom respektiert und schützt die Privatsphäre aller Nutzer des Dienstes.\n\n1. Kameraberechtigung: Wird ausschließlich zum Aufnehmen von Fotos verwendet. Es werden keine Bilddaten erfasst oder hochgeladen.\n\n2. Berechtigung für die Fotomediathek: Wird ausschließlich zum Auswählen und Speichern von Fotos verwendet. Alle Fotos werden lokal auf deinem Gerät gespeichert.\n\n3. Datensicherheit: Alle von dir aufgenommenen Fotos werden lokal auf deinem Gerät gespeichert. Wir greifen nicht auf deine Daten zu und laden sie nicht hoch.\n\n4. Dienste von Drittanbietern: Diese App enthält keine Analyse- oder Werbedienste von Drittanbietern.\n\nWende dich bei Fragen an uns.';

