  }

  @override
  String get platformTutorialStepsHeading => 'Optimierungsschritte';

  @override
  String get platformTutorialTipsHeading => 'Tipp';

  @override
  String get platformTutorialTipsDescription =>
      'Kehre nach diesen Einstellungen zur Seite „Hintergrundoptimierung“ zurück und prüfe, ob der Status aktualisiert wurde. Wenn weiterhin Probleme auftreten, sieh dir die Anleitung für eine andere Plattform an oder melde das Problem auf GitHub.';

  @override
  String get platformTutorialAndroidStep1Title => 'Akkuoptimierung ausschalten';

  @override
  String get platformTutorialAndroidStep1Description =>
      'Öffne Einstellungen → Apps → Stroom → Akku und wähle „Uneingeschränkt“ oder „Nicht optimieren“. Du kannst auf der Seite „Hintergrundoptimierung“ dieser App auch auf „Akkusparen deaktivieren“ tippen, um Stroom zur Ausnahmeliste der Energieverwaltung hinzuzufügen. Die Pfade unterscheiden sich je nach Gerätehersteller.';

  @override
  String get platformTutorialAndroidStep2Title =>
      'Hintergrundaktivität zulassen';

  @override
  String get platformTutorialAndroidStep2Description =>
      'Öffne Einstellungen → Apps → Stroom und aktiviere „Hintergrundaktivität zulassen“ und „Autostart zulassen“. Bei einigen Smartphones muss Autostart auch im Sicherheitscenter oder Telefonmanager zugelassen werden.';

  @override
  String get platformTutorialAndroidStep3Title => 'Hintergrundprozess sperren';

  @override
  String get platformTutorialAndroidStep3Description =>
      'Wische in der Ansicht der zuletzt verwendeten Apps auf der Stroom-Karte nach unten oder tippe auf das Schlosssymbol, damit das System die App nicht entfernt.';

  @override
  String get platformTutorialAndroidStep4Title =>
      'Benachrichtigungen erlauben (Android 13 und neuer)';

  @override
  String get platformTutorialAndroidStep4Description =>
      'Ab Android 13 ist eine Benachrichtigungsberechtigung erforderlich. Ohne sie wird die Vordergrundbenachrichtigung für den Hintergrunddienst ausgeblendet, der Dienst läuft jedoch weiter. Die App fragt beim ersten Tippen auf „Dienst starten“ nach der Berechtigung. Du kannst sie auch unter Einstellungen → Apps → Stroom → Benachrichtigungen aktivieren.';

  @override
  String get platformTutorialAndroidStep5Title => 'Akkuoptimierung ignorieren';

  @override
  String get platformTutorialAndroidStep5Description =>
      'Wenn du in Stroom „Benachrichtigungen zum Aufgabenabschluss“ aktivierst, fordert die App die zugehörige Berechtigung an. Du kannst auch unter Einstellungen → Apps → Spezieller App-Zugriff → Akkuoptimierung prüfen, ob für Stroom „Nicht optimieren“ eingestellt ist.';

  @override
  String get platformTutorialAndroidStep6Title =>
      'Autostart und Hintergrundverwaltung auf Android-Geräten';

  @override
  String get platformTutorialAndroidStep6Description =>
      'Gerätehersteller fügen häufig eigene Einstellungen für Hintergrundaktivität hinzu:\n• Xiaomi/Redmi (MIUI/HyperOS): Einstellungen → Apps → Berechtigungen → Autostart; Stroom zulassen. Öffne anschließend Akku → App-Akkusparen → Stroom → Keine Einschränkungen.\n• Huawei/Honor (EMUI/HarmonyOS): Einstellungen → Apps → App-Start → Stroom → Manuell verwalten; automatischen Start, sekundären Start und Hintergrundaktivität zulassen.\n• OPPO/OnePlus/realme (ColorOS): Einstellungen → Akku → App-Akkuverwaltung → Stroom; uneingeschränkte Hintergrundaktivität zulassen.\n• vivo/iQOO (OriginOS): iManager → App-Verwaltung → Autostart; Stroom zulassen.';

  @override
  String get platformTutorialAndroidStep7Title =>
      'Sperrbildschirm-Bereinigung und Energiesparmodi ausschalten';

  @override
  String get platformTutorialAndroidStep7Description =>
      'Öffne Einstellungen → Akku und schalte „Energiesparen“ oder „Ultrasparen“ aus. Stelle außerdem „Speicher nach Sperren leeren“ auf „Nicht leeren“. Energiesparmodi schränken Hintergrundaktivität ein und können den Abschluss von Aufgaben beeinträchtigen.';

  @override
  String get platformTutorialIosStep1Title =>
      'Hintergrundaktualisierung aktivieren';

  @override
  String get platformTutorialIosStep1Description =>
      'Öffne Einstellungen → Allgemein → Hintergrundaktualisierung, suche Stroom und aktiviere die Option. Für die beste Nutzung wählst du „WLAN und mobile Daten“.';

  @override
  String get platformTutorialIosStep2Title => 'Benachrichtigungen erlauben';

  @override
  String get platformTutorialIosStep2Description =>
      'Öffne Einstellungen → Mitteilungen → Stroom und aktiviere „Mitteilungen erlauben“. Aktiviere Banner und Mitteilungszentrale, damit du zeitnah über Aufgaben informiert wirst.';

  @override
  String get platformTutorialIosStep3Title => 'Stromsparmodus ausschalten';

  @override
  String get platformTutorialIosStep3Description =>
      'Öffne Einstellungen → Batterie und schalte den „Stromsparmodus“ aus. Solange dieser Modus aktiv ist, schränkt das System Hintergrundaktivitäten ein.';

  @override
  String get platformTutorialIosStep4Title =>
      'Einschränkungen für Hintergrundaktivität unter iOS beachten';

  @override
  String get platformTutorialIosStep4Description =>
      'Vor iOS 26 dürfen Apps nicht wie Android-Apps dauerhaft im Hintergrund bleiben. Das System gewährt Apps nur zu bestimmten Zeiten, etwa bei der Hintergrundaktualisierung, bei Standortupdates oder während der Audiowiedergabe, kurzzeitig Ausführungszeit und kann lange laufende Aufgaben unterbrechen. Wir empfehlen:\n• Lasse Stroom bei länger laufenden Aufgaben im Vordergrund.\n• Kehre regelmäßig zur App zurück, um ihre Hintergrundzeit zu erneuern.\n• Aktiviere für wichtige Aufgaben „Benachrichtigungen zum Aufgabenabschluss“.';

  @override
  String get platformTutorialIosStep5Title => 'Tipps für laufende Aufgaben';

  @override
  String get platformTutorialIosStep5Description =>
      'iOS 26 und neuer unterstützen dauerhafte Hintergrundaufgaben. Aufgaben laufen normalerweise weiter, wenn du zu einer anderen App wechselst oder den Bildschirm sperrst. Bei knappen Ressourcen kann das System sie jedoch beenden; der Fortschritt erscheint auf dem Sperrbildschirm.\n\nÄltere iOS-Versionen unterstützen keine dauerhaften Hintergrundaufgaben. Kehre alle paar Minuten zur App zurück (5–10 Minuten sind ein Richtwert; das System entscheidet), um die Hintergrundzeit zu erneuern und eine Unterbrechung zu vermeiden.\n\nWische Stroom unter keiner Version im App-Umschalter weg; dadurch werden alle laufenden Aufgaben sofort beendet.';

  @override
  String get platformTutorialIosStep6Title => 'App im Vordergrund halten';

  @override
  String get platformTutorialIosStep6Description =>
      'Unter iOS-Versionen vor 26 ist die Hintergrundzeit für Apps begrenzt. Lasse Stroom bei länger laufenden Aufgaben im Vordergrund oder kehre regelmäßig zur App zurück, um diese Zeit zu verlängern.';

  @override
  String get platformTutorialWindowsStep1Title =>
      'Beim Schließen des Fensters minimieren';

  @override
  String get platformTutorialWindowsStep1Description =>
      'Standardmäßig wird Stroom beim Klicken auf die Schließen-Schaltfläche in die Systemleiste neben der Uhr minimiert und kann weiterlaufen. Stelle die App über das Symbol in der Systemleiste oder den Menüpunkt „Hauptfenster anzeigen“ wieder her. Beende die App nicht, solange Aufgaben laufen. Verwende zum Beenden „Anwendung vollständig beenden“ auf der Seite „Hintergrundoptimierung“ oder wähle „Stroom beenden“ im Menü der Systemleiste.';

  @override
  String get platformTutorialWindowsStep2Title =>
      'Energiesparmodus ausschalten';

  @override
  String get platformTutorialWindowsStep2Description =>
      'Öffne Einstellungen → System → Netzbetrieb und Energiesparen und schalte den Energiesparmodus aus. Du kannst ihn auch so einstellen, dass er erst unter einem gewählten Akkustand aktiviert wird.';

  @override
  String get platformTutorialWindowsStep3Title => 'Hintergrund-Apps zulassen';

  @override
  String get platformTutorialWindowsStep3Description =>
      'Öffne Einstellungen → Datenschutz und Sicherheit → Hintergrund-Apps, suche Stroom und vergewissere dich, dass die App aktiviert ist. Öffne unter Windows 11 Einstellungen → Apps → Installierte Apps → Stroom → Erweiterte Optionen → Berechtigungen für Hintergrund-Apps und wähle „Immer“ aus.';

  @override
  String get platformTutorialWindowsStep4Title =>
      'Energiesparmodus ausschalten (optional)';

  @override
  String get platformTutorialWindowsStep4Description =>
      'Damit Stroom lange ausgeführt werden kann, öffne Einstellungen → System → Netzbetrieb und stelle „Ruhezustand“ auf „Nie“ (nur im Netzbetrieb).';

  @override
  String get platformTutorialWindowsStep5Title =>
      'Stroom zum Autostart hinzufügen';

  @override
  String get platformTutorialWindowsStep5Description =>
      'Öffne den Task-Manager (Ctrl+Shift+Esc) → Autostart, suche Stroom und wähle mit der rechten Maustaste „Aktivieren“. Oder öffne Einstellungen → Apps → Autostart und aktiviere Stroom.';

  @override
  String get platformTutorialMacosStep1Title =>
      'Beim Schließen des Fensters minimieren';

  @override
  String get platformTutorialMacosStep1Description =>
      'Standardmäßig läuft Stroom nach dem Schließen des Fensters in der Menüleiste oben rechts weiter. Klicke auf das Symbol in der Menüleiste oder wähle „Hauptfenster anzeigen“, um die App wiederherzustellen. Beende die App nicht, solange Aufgaben laufen. Verwende zum Beenden „Anwendung vollständig beenden“ auf der Seite „Hintergrundoptimierung“ oder wähle „Stroom beenden“ im Menü der Menüleiste.';

  @override
  String get platformTutorialMacosStep2Title => 'Benachrichtigungen erlauben';

  @override
  String get platformTutorialMacosStep2Description =>
      'Öffne Systemeinstellungen → Mitteilungen → Stroom und aktiviere „Mitteilungen erlauben“. Wir empfehlen, sowohl Banner als auch die Mitteilungszentrale zu aktivieren.';

  @override
  String get platformTutorialMacosStep3Title =>
      'Stromsparmodus ausschalten (MacBook)';

  @override
  String get platformTutorialMacosStep3Description =>
      'Öffne Systemeinstellungen → Batterie → Netzteil und schalte den „Stromsparmodus“ aus. Dieser Modus schränkt Hintergrundaktivitäten ein.';

  @override
  String get platformTutorialMacosStep4Title => 'App aktiv halten';

  @override
  String get platformTutorialMacosStep4Description =>
      'macOS schränkt Hintergrund-Apps nur wenig ein. Lasse bei länger laufenden Aufgaben das Stroom-Fenster geöffnet. Beende die App nicht sofort; es reicht, das Fenster zu schließen.';

  @override
  String get platformTutorialMacosStep5Title =>
      'Beim Anmelden starten (optional)';

  @override
  String get platformTutorialMacosStep5Description =>
      'Öffne Systemeinstellungen → Allgemein → Anmeldeobjekte und füge Stroom hinzu, damit die App beim Start des Computers automatisch geöffnet wird.';

  @override
  String get platformTutorialLinuxStep1Title =>
      'Beim Schließen des Fensters minimieren';

  @override
  String get platformTutorialLinuxStep1Description =>
      'Standardmäßig wird Stroom beim Schließen des Fensters in der Systemleiste ausgeblendet (erfordert eine Desktopumgebung mit StatusNotifierItem-Unterstützung und libayatana-appindicator3-dev beim Erstellen). Über den Menüpunkt „Hauptfenster anzeigen“ im Menü der Systemleiste kannst du die App wiederherstellen. Beende die App nicht, solange Aufgaben laufen. Verwende zum Beenden „Anwendung vollständig beenden“ auf der Seite „Hintergrundoptimierung“ oder wähle „Stroom beenden“ im Menü der Systemleiste.';

  @override
  String get platformTutorialLinuxStep2Title =>
      'Einstellungen der Desktopumgebung';

  @override
  String get platformTutorialLinuxStep2Description =>
      'Öffne je nach Desktopumgebung (GNOME, KDE, XFCE usw.) Systemeinstellungen → Apps, suche Stroom und vergewissere dich, dass Hintergrundaktivität nicht eingeschränkt ist.';

  @override
  String get platformTutorialLinuxStep3Title =>
      'systemd-Dienst verwenden (optional)';

  @override
  String get platformTutorialLinuxStep3Description =>
      'Für länger laufende Hintergrundaufgaben kannst du einen systemd-Benutzerdienst erstellen. Lege dazu eine stroom.service-Datei unter ~/.config/systemd/user/ an und setze ExecStart auf die Stroom-Programmdatei.';

  @override
  String get platformTutorialLinuxStep4Title => 'Ruhezustand deaktivieren';

  @override
  String get platformTutorialLinuxStep4Description =>
      'Setze bei einem Server oder Desktop, der lange laufen soll, HandleLidSwitch=ignore in /etc/systemd/logind.conf, um den Ruhezustand beim Schließen des Deckels zu verhindern.';

  @override
  String get platformTutorialLinuxStep5Title => 'Autostart aktivieren';

  @override
  String get platformTutorialLinuxStep5Description =>
      'Öffne unter GNOME Tweaks → Startprogramme → Hinzufügen und wähle Stroom aus. Alternativ kannst du eine stroom.desktop-Datei unter ~/.config/autostart/ erstellen.';

  @override
  String get platformTutorialWebStep1Title => 'Tab geöffnet lassen';

  @override
  String get platformTutorialWebStep1Description =>
      'Webbrowser unterstützen keine Hintergrunddienste. Lasse den Stroom-Tab geöffnet, solange Aufgaben laufen; beim Schließen des Tabs oder Aktualisieren der Seite werden sie sofort unterbrochen.';

  @override
  String get platformTutorialWebStep2Title =>
      'Browser daran hindern, den Tab anzuhalten';

  @override
  String get platformTutorialWebStep2Description =>
      'Browser frieren möglicherweise inaktive Tabs im Hintergrund ein, um Ressourcen zu sparen. Lasse den Stroom-Tab im Vordergrund, während Aufgaben laufen, oder interagiere regelmäßig mit der Seite, damit sie aktiv bleibt.';

